/* EVO ICL Vault Lab — static, aggregate-data research workstation. */
'use strict';
const M=VaultMath, D=VaultData, model=D.model, study=D.research, followModel=D.followup;
const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const n=(value,digits=0)=>Number.isFinite(Number(value))?Number(value).toFixed(digits):'—';
const pct=value=>n(value*100)+'%';
const initialEye=(extra={})=>({acd:3.2,lt:3.63,stsh:11.8,stsv:12.2,wtw:11.6,size:12.6,toric:1,angle:0,source:'measured',...extra});
const state={lang:'zh',page:'overview',eye:'OD',bilateral:true,level:95,target:[250,750],eyes:{OD:initialEye(),OS:initialEye({acd:3.18,lt:3.66,stsh:11.75,stsv:12.16,angle:90})},pinned:[],follow:{OD:{},OS:{}},text:'',batch:'',parsed:{},batchOutput:[],ocrText:'',importBusy:false};
const L=(zh,en)=>state.lang==='zh'?zh:en;
const F={acd:['前房深度 ACD','Anterior chamber depth'],lt:['晶状体厚度 LT','Lens thickness'],stsh:['水平沟径 STS-H','Horizontal sulcus'],stsv:['垂直沟径 STS-V','Vertical sulcus'],wtw:['白到白 WTW','White-to-white'],size:['ICL 尺寸','ICL size'],toric:['散光型 Toric','Toric lens'],angle:['植入方位 θ','Implantation angle'],sts_eff:['轴向有效沟径','Effective sulcus'],sin2:['方位 sin²θ','Orientation sin²θ']};
const name=key=>F[key]?L(...F[key]):key;
const pages=[
 ['overview','◫','研究概览','Study overview','OVERVIEW','从原始数据到可验证的预测','From source data to verifiable predictions','本次重跑采用明确的清洗规则、患者分组嵌套验证与独立年份测试。','Reconstructed cleaning rules, nested patient-grouped validation and a held-out year.'],
 ['experiment','◎','拱高实验室','Vault experiment','VAULT EXPERIMENT','让测量、模型与不确定度同屏','Measurements, model and uncertainty','默认值为合成示例。模型描述条件关联，改变尺寸或方位不等于因果干预结果。','Defaults are synthetic examples. Model associations are not causal effects of changing size or orientation.'],
 ['scenarios','▦','参数情景','Parameter scenarios','PARAMETER EXPLORATION','比较情景，理解模型的敏感性','Explore scenarios and sensitivity','所有组合只作研究模拟，不给出临床尺寸或方位推荐。','All combinations are research simulations, not clinical lens or orientation recommendations.'],
 ['followup','⌁','随访研究','Follow-up research','LONGITUDINAL RESEARCH','用已观测信息研究后续变化','Learn from observed follow-up','术前模型与术后随访模型分别评估。1 个月实测值只能用于之后的终点。','Preoperative and postoperative models are evaluated separately. Observed month-one vault predicts only later outcomes.'],
 ['import','⇥','导入与批量','Import & batch','DATA WORKSPACE','录入更顺畅，字段可复核','Import, inspect and validate','文本、图片、PDF 与 CSV 在本浏览器处理。请仅使用合成或经批准的研究数据。','Text, images, PDF and CSV are processed in this browser. Use synthetic or authorized research data.'],
 ['evidence','≋','方法与证据','Methods & evidence','MODEL EVIDENCE','每一个结果都能追溯','Trace every result','这里展示患者分组验证、时间测试、亚组审查与数据清洗边界。','Inspect patient-grouped validation, temporal testing, subgroup limitations and cleaning rules.'],
 ['poster','▤','壁报与报告','Poster & reporting','SCIENTIFIC COMMUNICATION','把研究整理成一张清楚的壁报','A clear scientific poster','已发表同类壁报用于判断主题匹配；本稿仍待会议规格、作者与伦理信息确认。','Published comparable posters inform topic fit. Conference specifications and author/ethics metadata are pending.']
];
const labels={mean:['训练均值','Training mean'],ols_anatomy:['水平沟径 OLS','Horizontal STS OLS'],ols_axis:['轴向匹配 OLS','Axis-matched OLS'],ridge_orientation:['方位 Ridge','Orientation Ridge'],ridge_extended:['扩展 Ridge','Extended Ridge'],elastic_net:['Elastic net','Elastic net'],random_forest:['随机森林','Random forest'],hist_gradient:['直方图提升','Histogram boosting'],gradient_boost:['梯度提升','Gradient boosting'],svr:['支持向量回归','SVR'],xgboost:['XGBoost','XGBoost']};
const modelLabel=key=>labels[key]?L(...labels[key]):key;
const prediction=eye=>M.predict(state.eyes[eye],model,{level:state.level,low:state.target[0],high:state.target[1]});
let toastTimer,ocrWorker=null,ocrGeneration=0;
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3500);}
function panel(title,body,extra='',pad=true){return `<section class="panel"><div class="panel-head"><h2>${title}</h2>${extra}</div>${pad?`<div class="panel-pad">${body}</div>`:body}</section>`;}
function metric(label,value,unit,caption,primary=false){return `<div class="metric-card${primary?' primary':''}"><label>${label}</label><div class="metric-value">${value}<small>${unit}</small></div><div class="metric-caption">${caption}</div></div>`;}
function note(text,amber=false){return `<div class="callout${amber?' amber':''}"><span class="callout-icon">${amber?'!':'i'}</span><div>${text}</div></div>`;}
function svg(body,width=600,height=240,description='Research chart'){return `<svg class="chart-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(description)}">${body}</svg>`;}
function barChart(rows,max=160){const w=560,h=rows.length*40+30;return svg(rows.map((row,i)=>{const y=i*40+14;return `<text x="0" y="${y+13}">${esc(row.label)}</text><rect x="167" y="${y}" height="21" rx="4" width="${row.value/max*315}" fill="${row.selected?'#0d8b84':'#c8dcee'}"/><text x="${175+row.value/max*315}" y="${y+14}" style="fill:#365774;font-size:12px">${n(row.value,1)}</text>`;}).join('')+`<text x="167" y="${h-2}">MAE · μm</text>`,w,h,L('模型误差比较','Model error comparison'));}
function calibrationChart(){const bins=study.calibration_bins,w=540,h=260,pad=40,max=800;const scale=value=>pad+value/max*(w-pad*2),sy=value=>h-pad-value/max*(h-pad*2);let body='';[0,200,400,600,800].forEach(v=>{body+=`<line x1="${pad}" y1="${sy(v)}" x2="${w-pad}" y2="${sy(v)}" stroke="#edf2f7"/><text x="${pad-10}" y="${sy(v)+4}" text-anchor="end">${v}</text><text x="${scale(v)}" y="${h-pad+20}" text-anchor="middle">${v}</text>`;});body+=`<line x1="${pad}" y1="${sy(0)}" x2="${scale(800)}" y2="${sy(800)}" stroke="#a7bdce" stroke-dasharray="5 5"/>`;body+=bins.map(b=>`<circle cx="${scale(b.predicted)}" cy="${sy(b.observed)}" r="${Math.min(10,4+Math.sqrt(b.n)/3)}" fill="#176bbd" opacity=".8"><title>n=${b.n}; ${n(b.predicted)}→${n(b.observed)}</title></circle>`).join('');body+=`<text x="${w/2}" y="${h-2}" text-anchor="middle">${L('预测分箱均值','Binned mean prediction')} · μm</text><text x="${pad}" y="15">${L('实测均值','Observed mean')} · μm</text>`;return svg(body,w,h,L('校准分箱图，第一轮折外预测','Calibration bins from the first outer-CV repetition'));}
function overview(){const cv=model.research_validation,t=model.temporal_test,c=study.cohort;
 $('content').innerHTML=`<div class="metric-strip">${metric(L('原始登记队列','Registry cohort'),c.source.eyes,L('眼','eyes'),L('201 名患者记录 · 早期终点 397 眼','201 patient records · 397 early outcomes'))}${metric(L('患者分组验证 MAE','Patient-grouped CV MAE'),n(cv.mae),'μm',L('341 眼 · 173 人 · 嵌套 3×5 折','341 eyes · 173 patients · nested 3×5 folds'),true)}${metric(L('时间测试 MAE','Temporal-test MAE'),n(t.mae),'μm',L('2025 年 · 29 眼 / 15 人','2025 · 29 eyes / 15 patients'))}${metric(L('实测 1 月 → 6 月','Observed 1 mo → 6 mo'),n(followModel.validation.mae),'μm',L('随访模型 · 281 眼分组验证','Follow-up model · 281 eyes grouped CV'))}</div>
 <div class="grid-wide">${panel(L('模型比较：复杂度没有自动带来收益','Model comparison: complexity does not guarantee gains'),barChart(['mean','ols_anatomy','ols_axis','ridge_orientation','random_forest','xgboost'].filter(k=>study.models[k]).map(k=>({label:modelLabel(k),value:study.models[k].mae,selected:k==='ridge_orientation'})))+`<p class="section-note">${L('全部 11 个候选模型使用相同患者分组。调参在内层进行，2025 年不参与模型选择。','All 11 candidates share patient splits. Tuning is confined to inner folds; 2025 is excluded from selection.')}</p>`,`<span class="tag teal">${L('默认：6 变量 Ridge','Default: 6-feature Ridge')}</span>`)}${panel(L('这次重跑改变了什么','What changed in this reanalysis'),`<div class="insight-list">${[[L('缺失值与方位重新核对','Reconstructed missingness and orientation'),L('柱镜空白不再自动当作 0；ST​​S/LT 异常值有明确规则。','Blank cylinder is not automatically zero. STS/LT anomalies follow explicit rules.')],[L('所有预测系数联合拟合','All coefficients jointly fitted'),L('移除旧的样本内残差方位加项，方位与解剖变量共同估计。','Replace the old in-sample residual adjustment with a jointly fitted orientation term.')],[L('保留时间测试的真实结果','Retain the temporal-test result'),L('95% 区间默认展示；80% 区间在新年份覆盖不足，明确标注。','Show 95% intervals by default; explicitly report undercoverage of 80% intervals in the later year.')],[L('公开代码与汇总，不公开逐眼行','Publish code and summaries, not individual rows'),L('数据源哈希、规则、分析脚本、模型与壁报素材统一归档。','Archive source hash, rules, analysis, models and poster materials together.')]].map(([a,b])=>`<div class="insight"><span class="insight-dot"></span><div><b>${a}</b><p>${b}</p></div></div>`).join('')}</div>`)}</div>
 <div class="grid-wide space-top">${panel(L('验证结构','Validation structure'),`<div class="workflow-steps"><div class="workflow-step"><small>DEVELOPMENT</small><b>2022–2024</b><span>341 ${L('眼','eyes')} · 173 ${L('人','patients')}</span></div><span class="workflow-arrow">→</span><div class="workflow-step"><small>NESTED VALIDATION</small><b>${L('患者分组 3 × 5 折','Patient-grouped 3 × 5')}</b><span>${L('内层 4 折调参','4 inner folds for tuning')}</span></div><span class="workflow-arrow">→</span><div class="workflow-step"><small>TEMPORAL TEST</small><b>2025</b><span>29 ${L('眼','eyes')} · 15 ${L('人','patients')}</span></div></div><div class="import-actions"><button class="button blue" data-go="experiment">${L('打开拱高实验室','Open vault experiment')} →</button><button class="button" data-go="evidence">${L('查看完整证据','Inspect study evidence')}</button></div>`)}${panel(L('研究定位','Research positioning'),note(L('内部验证支持透明模型的研究价值。时间测试较小且区间覆盖发生变化，仍需独立中心验证；当前不支持自动手术方案选择。','Internal validation supports a transparent research model. The small temporal test shows changing interval coverage; independent-centre validation is required. Automated surgical plan selection is unsupported.'))+`<div class="import-actions"><button class="button" data-go="poster">${L('壁报适配与后续选题','Poster fit and next studies')} ↗</button></div>`)}</div>`;
}
function eyeToolbar(){return `<div class="experiment-toolbar"><div class="segmented dark">${['OD','OS'].filter(e=>e==='OD'||state.bilateral).map(e=>`<button data-eye="${e}" class="${state.eye===e?'active':''}"><span class="eye-indicator ${e==='OS'?'os':''}"></span>${e} · ${e==='OD'?L('右眼','Right eye'):L('左眼','Left eye')}</button>`).join('')}</div><div class="controls"><label><input type="checkbox" id="bilateral" ${state.bilateral?'checked':''}> ${L('双眼','Both eyes')}</label><label for="level">${L('预测区间','Prediction interval')}</label><select id="level"><option value="95" ${state.level===95?'selected':''}>95% ${L('默认','default')}</option><option value="80" ${state.level===80?'selected':''}>80%</option></select><button class="button small" data-action="reset-eye">${L('重置演示','Reset demo')}</button></div></div>`;}
function measurement(key,low,high,step,help=''){const value=state.eyes[state.eye][key];return `<div class="field ${key==='angle'?'field-angle':''}"><div class="field-label"><label for="num-${key}">${name(key)}</label><small>${key==='angle'?'°':'mm'}</small></div><div class="measure-control"><input type="range" id="range-${key}" aria-label="${esc(name(key))}" data-field="${key}" min="${low}" max="${high}" step="${step}" value="${esc(value)}"><input type="number" id="num-${key}" data-field="${key}" min="${M.ranges[key]?.[0]??low}" max="${M.ranges[key]?.[1]??high}" step="${step}" value="${esc(value)}"></div><div class="field-range"><span>${low}</span><span>${high}</span></div>${help?`<div class="hint">${help}</div>`:''}</div>`;}
function inputPanel(){const e=state.eyes[state.eye];return panel(`${state.eye} · ${L('研究输入','Research inputs')}`,measurement('acd',2.5,4.1,.01,L('角膜内皮至晶状体前表面，Pentacam 来源','From endothelium to anterior lens surface; Pentacam'))+measurement('lt',2.8,5,.01)+`<div class="source-field"><div class="divider"></div><div class="field-label"><label>${L('沟径来源','Sulcus source')}</label><small>${L('直接测量优先','Measured preferred')}</small></div><div class="source-control"><button class="button small ${e.source==='measured'?'teal':''}" data-source="measured">UBM ${L('实测','measured')}</button><button class="button small ${e.source==='wtw'?'teal':''}" data-source="wtw">WTW ${L('估计','estimated')}</button></div>${e.source==='measured'?measurement('stsh',10,13.8,.01)+measurement('stsv',10.5,14,.01):measurement('wtw',10,13.5,.01,L('探索性回退，未单独验证其预测区间','Exploratory fallback; its intervals are not separately validated'))}</div><div class="field"><div class="field-label"><label>${name('size')}</label><small>mm</small></div><div class="size-control">${M.sizes.map(s=>`<button data-size="${s}" class="${Number(e.size)===s?'active':''}">${s.toFixed(1)}</button>`).join('')}</div></div><div class="field"><div class="field-label"><label for="toric">${name('toric')}</label></div><select id="toric" style="width:100%"><option value="0" ${Number(e.toric)===0?'selected':''}>${L('非散光型','Non-toric')}</option><option value="1" ${Number(e.toric)===1?'selected':''}>${L('散光型','Toric')}</option></select></div>${measurement('angle',0,180,1,L('0° 水平 · 90° 垂直；斜轴是数学插值','0° horizontal · 90° vertical; oblique axes are mathematical interpolation'))}`,`<span class="tag">${L('会话输入','Session inputs')}</span>`,true).replace('class="panel"','class="panel input-panel"');}
function intervalGraphic(p){const w=600,margin=15,max=1100,x=value=>margin+M.clamp(value/max,0,1)*(w-margin*2);let body=`<rect x="${x(0)}" y="27" width="${x(250)-x(0)}" height="9" rx="4" fill="#eddde3"/><rect x="${x(250)}" y="27" width="${x(750)-x(250)}" height="9" fill="#bfe2db"/><rect x="${x(750)}" y="27" width="${x(1100)-x(750)}" height="9" rx="4" fill="#f0dec0"/>`;body+=`<rect x="${x(p.band[0])}" y="16" width="${Math.max(1,x(p.band[1])-x(p.band[0]))}" height="31" rx="6" fill="#176bbd12" stroke="#176bbd70"/><line x1="${x(p.y)}" x2="${x(p.y)}" y1="10" y2="51" stroke="#176bbd" stroke-width="2"/><circle cx="${x(p.y)}" cy="10" r="4" fill="#176bbd"/>`;[0,250,500,750,1000].forEach(v=>body+=`<text x="${x(v)}" y="70" text-anchor="middle">${v}</text>`);return svg(body,w,78,L('拱高与折外残差预测区间','Vault and out-of-fold-residual prediction interval')).replace('class="chart-svg"','class="chart-svg interval-svg"');}
function geometry(p){const e=p.resolved,angle=e.angle* Math.PI/180,rx=58,ry=58*e.stsv/e.stsh,cx=79,cy=78,ex=Math.cos(angle)*rx,ey=-Math.sin(angle)*ry;return `<div class="geometry-panel"><svg class="geometry-svg" viewBox="0 0 185 160" role="img" aria-label="${L('睫状沟椭圆与植入轴示意','Illustrative sulcus ellipse and implantation axis')}"><ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="#e8f3f8" stroke="#7ba7c2" stroke-width="1.4"/><line x1="18" y1="${cy}" x2="145" y2="${cy}" stroke="#bdcddd" stroke-dasharray="3 3"/><line x1="${cx}" y1="12" x2="${cx}" y2="144" stroke="#bdcddd" stroke-dasharray="3 3"/><line x1="${cx-ex}" y1="${cy-ey}" x2="${cx+ex}" y2="${cy+ey}" stroke="#176bbd" stroke-width="3"/><circle cx="${cx}" cy="${cy}" r="4" fill="#176bbd"/><text x="150" y="83" font-size="10" fill="#7d96a8">H</text><text x="75" y="12" font-size="10" fill="#7d96a8">V</text></svg><div class="geometry-caption"><b>${L('轴向匹配的解剖几何','Axis-matched anatomy')}</b><br>${L('示意图不代表影像重建或力学仿真。','Illustration, not image reconstruction or biomechanical simulation.')}<div class="geometry-stat"><div>STS<sub>eff</sub><b>${n(e.sts_eff,2)} mm</b></div><div>ICL − STS<sub>eff</sub><b>${n(e.size-e.sts_eff,2)} mm</b></div><div>θ<b>${n(e.angle)}°</b></div><div>sin²θ<b>${n(e.sin2,2)}</b></div></div></div></div>`;}
function resultHTML(){const p=prediction(state.eye);if(!p.valid)return `<div class="result-main"><div class="error-message">${L('请核对缺失值、单位或范围：','Check missing values, units or ranges: ')}${p.errors.map(name).join(' / ')}</div></div>`;const other=prediction(state.eye==='OD'?'OS':'OD');const cv=model.research_validation,t=model.temporal_test;const warnings=[];if(p.fallback)warnings.push(L('WTW 回退属于探索性估计，当前区间未对回退单独校准。','WTW fallback is exploratory; these intervals are not calibrated specifically for fallback.'));if(p.tails.length)warnings.push(L('这些参数位于队列边缘或斜轴插值区：','Tail-of-cohort inputs or oblique interpolation: ')+p.tails.map(name).join(' / '));if(state.level===80)warnings.push(L('标称 80% 区间在 2025 年仅覆盖 65.5%；请同时查看 95% 区间。','The nominal 80% interval covered only 65.5% in 2025; also inspect the 95% interval.'));return `<div class="result-main"><div class="result-top"><div><div class="readout-label">${state.eye} · ${L('术后 1 个月模型估计','One-month model estimate')}</div><div class="vault-readout" id="pointPrediction">${n(p.y)}<small>μm</small></div><div class="readout-note">${L('6 变量 Ridge · α=10 · 联合拟合','6-feature Ridge · α=10 · jointly fitted')}</div></div>${state.bilateral&&other.valid?`<div class="eye-mini"><span>${state.eye==='OD'?'OS':'OD'} ${L('对侧眼','contralateral')}</span><b>${n(other.y)} μm</b></div>`:`<span class="tag">${L('单眼视图','Single-eye view')}</span>`}</div><div class="interval-bar">${intervalGraphic(p)}</div><div class="interval-text"><span>${p.level}% ${L('预测区间','prediction interval')}<br><b>${n(p.band[0])} – ${n(p.band[1])} μm</b></span><span>${L('系数 bootstrap 95% 带','Coefficient bootstrap 95% band')}<br><b>${n(p.centerBand[0])} – ${n(p.centerBand[1])} μm</b></span></div><div class="probability-row">${[['low',L('低区间','Low range'),'<250 μm'],['middle',L('中间区间','Middle range'),'250–750 μm'],['high',L('高区间','High range'),'>750 μm']].map(([k,title,range])=>`<div class="probability-card ${k==='middle'?'center':''}"><label>${title}</label><b>${pct(p.probabilities[k])}</b><small>${range}</small><div class="mini-track"><i style="width:${p.probabilities[k]*100}%"></i></div></div>`).join('')}</div><p class="dense-note">${L('概率为开发集折外残差直方图的模型估计，未作独立事件概率校准。区间估计个体误差，bootstrap 带仅估计系数变动。','Probabilities are estimates from the development out-of-fold residual histogram, without independent event-probability calibration. Prediction intervals describe individual error; the bootstrap band describes coefficient variation.')}</p>${warnings.length?note(warnings.map(esc).join('<br>'),true):''}${geometry(p)}</div><div class="result-foot"><span class="dense-note">${L('当前情景','Current scenario')}: ${n(p.resolved.size,1)} mm / ${n(p.resolved.angle)}°</span><div><button class="button small" data-action="pin">${L('暂存情景','Pin scenario')}</button> <button class="button small" data-action="report">${L('研究小结','Research summary')}</button></div></div>`;}
function evidenceMini(){return `<div class="mini-evidence"><div><small>${L('患者分组验证 MAE','Patient-grouped CV MAE')}</small><b>${n(model.research_validation.mae)} μm</b><span>3 × 5 ${L('外层折','outer folds')}</span></div><div><small>${L('时间测试 MAE','Temporal-test MAE')}</small><b>${n(model.temporal_test.mae)} μm</b><span>29 ${L('眼 / 15 人','eyes / 15 patients')}</span></div><div><small>95% ${L('时间测试覆盖','temporal coverage')}</small><b>${pct(model.temporal_test.coverage95)}</b><span>${L('小样本，非外部验证','Small sample, not external validation')}</span></div></div>`;}
function percentileHTML(){const p=prediction(state.eye);if(!p.valid)return '';return `<div class="percentile-grid">${['acd','lt','stsh','stsv','size','angle'].map(k=>{const v=M.percentile(p.resolved[k],model.reference[k]);return `<div class="percentile-item"><span>${name(k)}<b>P${n(v)}</b></span><div class="percentile-track"><i style="width:${v}%"></i></div></div>`;}).join('')}</div><p class="dense-note space-top">${L('百分位由开发集 5% 分位点插值，仅表示队列位置，不等同于临床可靠性等级。','Percentiles interpolate development-cohort 5% quantiles. They describe cohort position, not validated clinical reliability.')}</p>`;}
function equation(){return `Vault<sub>1m</sub> = ${n(model.intercept,2)} ${model.features.map(k=>`${model.coefficients[k]>=0?'+':'−'} ${n(Math.abs(model.coefficients[k]),2)} × ${k==='sts_eff'?'STS<sub>eff</sub>':k==='sin2'?'sin²θ':k==='size'?'ICL':k.toUpperCase()}`).join(' ')}`;}
function experiment(){ $('content').innerHTML=eyeToolbar()+`<div class="experiment-grid">${inputPanel()}<div class="stack">${panel(L('模型结果','Model result'),'<div id="resultPanel"></div>',`<span class="tag teal">${L('研究估计','Research estimate')}</span>`,false)}${panel(L('验证摘要','Validation snapshot'),evidenceMini())}${panel(L('队列定位','Cohort position'),'<div id="percentilePanel"></div>')}</div></div><details class="equation-details space-top"><summary>${L('查看公式、单位和适用范围','Inspect the formula, units and scope')}</summary><div class="formula space-top">${equation()}<br>STS<sub>eff</sub> = 1 / √(cos²θ / STS-H² + sin²θ / STS-V²)</div><p>${L('ACD、LT、ICL、STS 单位为 mm；方位项与其他系数联合拟合。训练仅用 2022–2024，2025 保留为时间测试。','ACD, LT, ICL and STS are in mm. Orientation is jointly fitted. Training uses only 2022–2024; 2025 remains a temporal test.')}</p></details>`;refreshExperiment();}
function refreshExperiment(){if($('resultPanel'))$('resultPanel').innerHTML=resultHTML();if($('percentilePanel'))$('percentilePanel').innerHTML=percentileHTML();}
function combinations(){let rows=[];for(const size of M.sizes)for(const angle of [0,90]){const p=M.predict({...state.eyes[state.eye],size,angle},model,{level:state.level,low:state.target[0],high:state.target[1]});if(p.valid)rows.push({size,angle,p});}return rows;}
function scenarioRows(){return combinations().map(({size,angle,p})=>`<tr class="${Number(state.eyes[state.eye].size)===size&&Number(state.eyes[state.eye].angle)===angle?'selected':''}"><td>${size.toFixed(1)} mm · ${angle}°</td><td>${n(p.y)}</td><td>${n(p.band[0])} – ${n(p.band[1])}</td><td>${pct(p.probabilities.low)}</td><td>${pct(p.probabilities.middle)}</td><td>${pct(p.probabilities.high)}</td><td><b>${pct(p.probabilities.target)}</b></td><td><button class="button small" data-scenario="${size},${angle}">${L('查看','View')}</button></td></tr>`).join('');}
function heatmap(){const angles=[0,30,60,90,120,150,180];return `<div class="heatmap"><span></span>${angles.map(a=>`<span class="heat-label">${a}°</span>`).join('')}${M.sizes.map(s=>`<span class="heat-label">${s.toFixed(1)} mm</span>${angles.map(a=>{const p=M.predict({...state.eyes[state.eye],size:s,angle:a},model,{level:state.level,low:state.target[0],high:state.target[1]});const probability=p.valid?p.probabilities.target:0;return `<button class="heat-cell" data-scenario="${s},${a}" style="background:rgba(13,139,132,${.05+probability*.55});color:${probability>.65?'#fff':'#216461'}" aria-label="ICL ${s} ${a}° ${pct(probability)}">${p.valid?pct(probability):'—'}</button>`;}).join('')}`).join('')}</div>`;}
function sensitivity(){const e=state.eyes[state.eye],base=prediction(state.eye);if(!base.valid)return '';const rows=[['acd',.2],['lt',.2],['stsh',.2],['stsv',.2]].map(([key,delta])=>{const a=M.predict({...e,[key]:Number(e[key])-delta},model),b=M.predict({...e,[key]:Number(e[key])+delta},model);return {key,delta,lo:a.valid?a.y-base.y:0,hi:b.valid?b.y-base.y:0};});const max=Math.max(30,...rows.flatMap(r=>[Math.abs(r.lo),Math.abs(r.hi)]));return rows.map(r=>`<div class="sensitivity-row"><span>${name(r.key)}<br>±${r.delta} mm</span><div class="sensitivity-track"><i style="left:${50+Math.min(r.lo,r.hi)/max*45}%;width:${Math.abs(r.hi-r.lo)/max*45}%"></i></div><b>${n(r.lo)} / ${n(r.hi)} μm</b></div>`).join('')+`<p class="dense-note">${L('保持其他参数不变的模型响应；并非可执行的生理改变。','Model response with other inputs fixed, not an actionable physiological change.')}</p>`;}
function pinnedHTML(){if(!state.pinned.length)return `<div class="empty-state">${L('暂存一个情景，在这里并排比较','Pin a scenario to compare it here')}<p>${L('仅保留于本次浏览器会话，可显式导出 JSON。','Kept only in this browser session; JSON export is explicit.')}</p></div>`;return `<div class="table-scroll"><table><thead><tr><th>${L('情景','Scenario')}</th><th>ICL / θ</th><th>${L('估计','Estimate')}</th><th>PI</th><th></th></tr></thead><tbody>${state.pinned.map((r,i)=>`<tr><td>${r.eye} · ${i+1}</td><td>${r.eyeData.size} / ${r.eyeData.angle}°</td><td>${n(r.y)} μm</td><td>${n(r.band[0])} – ${n(r.band[1])} <small>(${r.level}%)</small></td><td><button class="button small" data-unpin="${i}">×</button></td></tr>`).join('')}</tbody></table></div>`;}
function scenarios(){ $('content').innerHTML=eyeToolbar()+note(L('大小和方位的关系来自非随机回顾性数据。情景表表示模型条件关联，不能当作“最优术式”排序。','Size and orientation associations derive from nonrandom retrospective data. This table is a conditional model exploration, not an optimal surgical plan ranking.'))+`<section class="panel space-top"><div class="panel-head"><h2>${L('4 尺寸 × 2 方位','4 sizes × 2 orientations')}</h2><span class="tag">${state.eye}</span></div><div class="table-tools"><div class="form-row"><label>${L('研究目标区','Research target')}</label><input class="target-input" type="number" id="targetLow" value="${state.target[0]}" min="0" max="1500" aria-label="Target lower limit"><span>–</span><input class="target-input" type="number" id="targetHigh" value="${state.target[1]}" min="0" max="1500" aria-label="Target upper limit"><span class="muted">μm</span></div><button class="button small" data-action="target-reset">250–750 μm</button></div><div class="table-scroll"><table><thead><tr><th>${L('情景','Scenario')}</th><th>${L('拱高 μm','Vault μm')}</th><th>${state.level}% PI</th><th>&lt;250</th><th>250–750</th><th>&gt;750</th><th>${L('目标区概率','Target probability')}</th><th></th></tr></thead><tbody id="scenarioRows">${scenarioRows()}</tbody></table></div></section><div class="grid-2 space-top">${panel(L('目标区概率 · 角度热图','Target probability · angle map'),'<div id="heatmap">'+heatmap()+'</div>'+`<p class="dense-note" style="padding:0 23px 20px">${L('斜轴取椭圆几何与 sin² 插值，未在各角度分别验证。','Oblique axes use elliptical geometry and sin² interpolation; each angle is not separately validated.')}</p>`,'',false)}${panel(L('测量敏感性','Measurement sensitivity'),sensitivity())}</div><div class="space-top">${panel(L('暂存情景','Pinned scenarios'),pinnedHTML(),`<button class="button small" data-action="export-json">JSON ↓</button>`)}</div>`;}
function lineChart(points,predicted=null){const w=620,h=250,pad=43,max=Math.max(850,...points.map(p=>p.value),predicted?.value||0);const x=day=>pad+(Math.log(day+1)/Math.log(181))*(w-pad*2),y=v=>h-pad-v/max*(h-pad*2);let body='';[0,250,500,750].forEach(v=>body+=`<line x1="${pad}" x2="${w-pad}" y1="${y(v)}" y2="${y(v)}" stroke="#edf2f7"/><text x="${pad-10}" y="${y(v)+4}" text-anchor="end">${v}</text>`);[1,30,90,180].forEach((v,i)=>body+=`<text x="${x(v)}" y="${h-pad+24}" text-anchor="middle">${[L('早期','Early'),L('1 月','1 mo'),L('3 月','3 mo'),L('6 月','6 mo')][i]}</text>`);if(points.length>1)body+=`<polyline points="${points.map(p=>`${x(p.day)},${y(p.value)}`).join(' ')}" fill="none" stroke="#176bbd" stroke-width="2"/>`;body+=points.map(p=>`<circle cx="${x(p.day)}" cy="${y(p.value)}" r="5" fill="#176bbd"/><text x="${x(p.day)}" y="${y(p.value)-13}" text-anchor="middle">${n(p.value)}</text>`).join('');if(predicted)body+=`<line x1="${x(180)}" x2="${x(180)}" y1="${y(predicted.band[0])}" y2="${y(predicted.band[1])}" stroke="#0d8b84" stroke-width="2"/><circle cx="${x(180)}" cy="${y(predicted.value)}" r="5" fill="#fff" stroke="#0d8b84" stroke-width="2"/>`;return svg(body,w,h,L('当前会话的实测拱高与6个月研究估计','Session observations and exploratory six-month estimate'));}
function followEstimate(){const eye=state.eyes[state.eye],observed=state.follow[state.eye],resolved=M.features(eye,model);if(resolved.errors.length||!M.finite(observed.month1)||Number(observed.month1)<0||Number(observed.month1)>1500)return null;const values={...resolved.values,month1:Number(observed.month1)},value=M.linear(followModel,values);return {value,band:[value+followModel.residual_quantiles[2],value+followModel.residual_quantiles[3]]};}
function followupResult(){const observation=state.follow[state.eye];const points=[['early',1],['month1',30],['month3',90],['month6',180]].filter(([key])=>M.finite(observation[key])&&Number(observation[key])>=0&&Number(observation[key])<=1500).map(([key,day])=>({day,value:Number(observation[key])}));const estimate=followEstimate();return `<div>${points.length?lineChart(points,estimate):'<div class="empty-state">'+L('录入一项实测拱高后，显示会话曲线','Add an observed vault to see the session curve')+'</div>'}${estimate?`<div class="eye-mini"><span>${L('探索性 6 个月估计','Exploratory 6-month estimate')}</span><b>${n(estimate.value)} μm</b><span>95% PI ${n(estimate.band[0])} – ${n(estimate.band[1])}</span></div>`:note(L('输入实测 1 个月拱高后，才计算后续 6 个月研究估计。','Enter observed one-month vault to estimate the later six-month outcome.'))}</div>`;}
function followup(){const observed=state.follow[state.eye],comparison=study.longitudinal.six_month_comparison;$('content').innerHTML=eyeToolbar()+`<div class="grid-2">${panel(L('实测随访 · 当前会话','Observed follow-up · current session'),`<div class="follow-inputs">${[['early',L('早期','Early')],['month1',L('1 个月','1 month')],['month3',L('3 个月','3 months')],['month6',L('6 个月','6 months')]].map(([key,title])=>`<label>${title} · μm<input type="number" data-observed="${key}" id="obs-${key}" value="${esc(observed[key]??'')}" min="0" max="1500" placeholder="—"></label>`).join('')}</div><div id="followupResult" class="space-top">${followupResult()}</div><p class="dense-note space-top">${L('曲线仅连接已录入观测；缺失时点不填补。6 个月模型在配对样本重拟合，仅有内部验证。','The curve connects entered observations only. Missing visits remain missing. The six-month model is refitted on paired observations and has internal validation only.')}</p>`)}${panel(L('同一批眼的模型比较','Model comparison on the same eyes'),barChart([['preoperative_only',L('仅术前参数','Preoperative only')],['plus_observed_early',L('+ 实测早期','+ observed early')],['plus_observed_month1',L('+ 实测 1 月','+ observed 1 month')]].map(([k,label])=>({label,value:comparison[k].mae,selected:k==='plus_observed_month1'})),115)+note(L('281 眼 / 142 名患者；外层 5 折患者分组，内层调参。较小误差依赖已经发生的术后测量，不能替代术前预测。','281 eyes / 142 patients; grouped five-fold outer validation and inner tuning. Lower error depends on an observed postoperative measurement and cannot replace preoperative prediction.')))}</div><div class="space-top">${panel(L('配对随访变化','Paired follow-up changes'),`<div class="table-scroll"><table><thead><tr><th>${L('终点','Endpoint')}</th><th>n ${L('眼','eyes')}</th><th>${L('同批早期均值','Paired early mean')}</th><th>${L('随访均值','Follow-up mean')}</th><th>${L('同眼变化','Within-eye change')}</th><th>${L('患者聚类 95% CI','Patient-cluster 95% CI')}</th></tr></thead><tbody>${['month1','month3','month6','year1'].map(k=>{const r=study.longitudinal[k];return `<tr><td>${({month1:L('1 个月','1 month'),month3:L('3 个月','3 months'),month6:L('6 个月','6 months'),year1:L('1 年','1 year')})[k]}</td><td>${r.n}</td><td>${n(r.early.mean,1)}</td><td>${n(r.followup.mean,1)}</td><td>${n(r.change.mean,1)}</td><td>${n(r.change_ci95[0],1)} – ${n(r.change_ci95[1],1)}</td></tr>`;}).join('')}</tbody></table></div><p class="dense-note space-top">${L('每个时点使用有配对观测的眼。1 年只剩 65 眼，不能将这些均值连线理解为完整队列的自然时程。','Each time point uses eyes with paired observations. Only 65 eyes remain at one year; the available-case means are not a complete-cohort natural-history trajectory.')}</p>`)}</div>`;}

const sampleText='Synthetic anterior-segment report\nACD: 3.20 mm\nLT: 3.63 mm\nSTS-H: 11.80 mm\nSTS-V: 12.20 mm\nWTW: 11.60 mm\nICL size: 12.6 mm\nToric: 1\nAngle: 0';
const sampleCSV='acd,lt,stsh,stsv,size,toric,angle,vault\n3.2,3.63,11.8,12.2,12.6,1,0,405\n3.18,3.66,11.75,12.16,12.6,1,90,330\n3.5,3.8,12.1,12.55,13.2,0,0,520';
function importPage(){ $('content').innerHTML=`<div class="grid-2">${panel(L('测量文本与本地 OCR','Measurement text & local OCR'),`<p class="section-note">${L('先识别，再逐字段复核。每次应用到明确的眼别。','Extract first, then review each field and apply to an explicit eye.')}</p><textarea id="measurementText" aria-label="Measurement report" placeholder="ACD 3.20 mm&#10;STS-H 11.80 mm&#10;STS-V 12.20 mm">${esc(state.text)}</textarea><div class="import-actions"><button class="button blue" data-action="parse">${L('识别字段','Extract fields')}</button><button class="button" data-action="sample-text">${L('合成示例','Synthetic example')}</button><label class="button"><input type="file" id="ocrFile" accept="image/png,image/jpeg,image/webp,application/pdf" hidden>${L('图片 / PDF OCR','Image / PDF OCR')} ↗</label></div><div class="import-meta"><span id="ocrStatus">${L('引擎首次使用联网下载；图片与文本在本机处理','First use downloads engines; images and text are processed locally')}</span><progress id="ocrProgress" max="1" value="0"></progress></div><div id="ocrPreview" class="space-top"></div><div id="parsedFields">${parsedFields()}</div><div class="import-actions"><button class="button teal" data-apply="OD">${L('应用至右眼 OD','Apply to OD')}</button><button class="button teal" data-apply="OS">${L('应用至左眼 OS','Apply to OS')}</button><button class="button small" data-action="clear-import">${L('清除输入','Clear inputs')}</button></div>`)}${panel(L('批量计算与独立数据验证','Batch calculation & independent-data evaluation'),`<p class="section-note">${L('CSV / TSV，最多 5000 行。保留支持的数字字段，忽略其他列；输出不带姓名或自由文本。','CSV / TSV, up to 5000 rows. Only supported numeric fields are retained; other columns are ignored. Exports omit names and free text.')}</p><textarea id="batchText" aria-label="Batch CSV" placeholder="acd,lt,stsh,stsv,size,toric,angle,vault">${esc(state.batch)}</textarea><div class="import-actions"><button class="button blue" data-action="batch-run">${L('运行批量','Run batch')}</button><button class="button" data-action="sample-csv">${L('合成示例','Synthetic example')}</button><label class="button"><input type="file" id="csvFile" accept=".csv,.tsv,.txt" hidden>${L('选择 CSV','Choose CSV')}</label><button class="button small" data-action="batch-export">CSV ↓</button></div><div id="batchMetrics"></div><div id="batchTable"></div>`)}</div><div class="space-top">${panel(L('会话交换与隐私','Session exchange & privacy'),`<div class="toolbar-row"><p class="section-note">${L('参数、随访与情景仅存在本次会话。JSON 和链接导出由你主动触发。','Inputs, observations and scenarios exist only in this session. JSON and link exports are explicit actions.')}</p><div class="import-actions"><button class="button" data-action="export-json">${L('导出 JSON','Export JSON')}</button><label class="button"><input type="file" id="jsonFile" accept="application/json,.json" hidden>${L('导入 JSON','Import JSON')}</label><button class="button" data-action="share">${L('分享合成参数','Share synthetic parameters')}</button><button class="button" data-action="wipe">${L('清空会话','Clear session')}</button></div></div>${note(L('识别结果不保证正确。图片上的身份信息不会被自动可靠打码；请先去标识再导入。下载第三方 OCR/PDF 引擎会连接 CDN，临床数据不上传至本项目服务器。','Extraction can be wrong. Visible identifiers in images are not automatically or reliably masked; de-identify before import. OCR/PDF engines download from a CDN; clinical data is not uploaded to this project server.'))}`)}</div>`;}
function parsedFields(){return `<div class="parsed-fields">${Object.entries(state.parsed).map(([key,value])=>`<label>${name(key)}<br><input type="number" data-parsed="${key}" value="${value}" step="0.01"><small>${L('需人工复核','Review required')}</small></label>`).join('')}</div>`;}
function parseMeasurements(text){const output={},lines=text.split(/\r?\n/);const regex={acd:/\bACD\b|前房深度/i,lt:/\bLT\b|晶状?体厚度/i,stsh:/STS[-_ ]?H\b|水平沟径/i,stsv:/STS[-_ ]?V\b|垂直沟径/i,wtw:/\bWTW\b|白到白/i,size:/ICL\s*(?:size|尺寸)|晶体尺寸/i,toric:/Toric|散光型/i,angle:/Angle|方位|角度/i};for(const [key,pattern] of Object.entries(regex)){for(const line of lines){const match=pattern.exec(line);if(!match)continue;const value=line.slice(match.index+match[0].length).match(/[-−]?\d+(?:\.\d+)?/);if(value&&M.finite(value[0])){output[key]=Number(value[0]);break;}}}return output;}
function batchRun(){state.batch=$('batchText').value;if(state.batch.length>2e6){toast(L('输入超过 2 MB','Input exceeds 2 MB'));return;}try{const rows=M.parseCSV(state.batch);state.batchOutput=rows.map(r=>{const e={};for(const key of ['acd','lt','stsh','stsv','wtw','size','toric','angle'])e[key]=M.finite(r[key])?Number(r[key]):'';e.source=r.source==='wtw'?'wtw':'measured';const p=M.predict(e,model,{level:state.level});return {row:r.row,p,vault:M.finite(r.vault)?Number(r.vault):null};});const valid=state.batchOutput.filter(r=>r.p.valid),pairs=valid.filter(r=>r.vault!==null&&r.vault>=0&&r.vault<=1500).map(r=>[r.p.y,r.vault]),metric=M.evaluate(pairs);$('batchMetrics').innerHTML=`<p class="section-note">${valid.length} / ${rows.length} ${L('行有效','valid rows')}</p>${metric?`<div class="mini-evidence"><div><small>MAE</small><b>${n(metric.mae)} μm</b></div><div><small>RMSE</small><b>${n(metric.rmse)} μm</b></div><div><small>R²</small><b>${metric.r2===null?'—':n(metric.r2,2)}</b></div></div><p class="dense-note">${L('本地载入数据的描述性评分。请确认它与训练数据独立；未自动计算患者聚类区间。','Descriptive scoring of your local input. Confirm independence from training data; patient-cluster intervals are not computed automatically.')}</p>`:''}`;$('batchTable').innerHTML=`<div class="table-scroll space-top"><table><thead><tr><th>${L('原文件行','Source row')}</th><th>${L('估计','Estimate')}</th><th>${state.level}% PI</th><th>${L('状态','Status')}</th></tr></thead><tbody>${state.batchOutput.slice(0,30).map(r=>`<tr><td>${r.row}</td><td>${r.p.valid?n(r.p.y):'—'}</td><td>${r.p.valid?n(r.p.band[0])+' – '+n(r.p.band[1]):'—'}</td><td>${r.p.valid?L('有效','Valid'):esc(r.p.errors.join('/'))}</td></tr>`).join('')}</tbody></table></div><p class="dense-note">${L('预览前 30 行；CSV 下载包含全部行。','Preview shows the first 30 rows; CSV download includes all rows.')}</p>`;}catch(error){toast(L('CSV 解析失败：','CSV parsing failed: ')+error.message);}}
async function loadOCR(file){if(state.importBusy)return;if(file.size>20e6){toast(L('文件超过 20 MB','File exceeds 20 MB'));return;}const generation=++ocrGeneration;state.importBusy=true;try{let canvases=[],text='';if(file.type==='application/pdf'){const pdfjs=await import('https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.worker.min.mjs';const pdf=await pdfjs.getDocument({data:await file.arrayBuffer(),isEvalSupported:false}).promise;for(let i=1;i<=Math.min(8,pdf.numPages);i++){const page=await pdf.getPage(i),parts=await page.getTextContent();const pageText=parts.items.map(item=>item.str+(item.hasEOL?'\n':' ')).join('');if(pageText.trim().length>20)text+=pageText+'\n';else{const viewport=page.getViewport({scale:1.5}),c=document.createElement('canvas');c.width=viewport.width;c.height=viewport.height;await page.render({canvasContext:c.getContext('2d'),viewport}).promise;canvases.push(c);}}await pdf.destroy();}else{if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('Unsupported image type');const bitmap=await createImageBitmap(file);if(bitmap.width*bitmap.height>40e6){bitmap.close();throw new Error('Image exceeds 40 megapixels');}const scale=Math.min(1,2400/bitmap.width),c=document.createElement('canvas');c.width=bitmap.width*scale;c.height=bitmap.height*scale;c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);bitmap.close();canvases.push(c);}if(canvases.length){if(!window.Tesseract)await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/dist/tesseract.min.js';script.onload=resolve;script.onerror=()=>reject(new Error('OCR engine download failed'));document.head.appendChild(script);});if(!ocrWorker)ocrWorker=await Tesseract.createWorker('eng+chi_sim',1,{logger:message=>{if(generation!==ocrGeneration)return;if($('ocrProgress')&&message.progress!=null)$('ocrProgress').value=message.progress;if($('ocrStatus'))$('ocrStatus').textContent=message.status;}});for(const canvas of canvases){if(generation!==ocrGeneration)break;const result=await ocrWorker.recognize(canvas);text+=result.data.text+'\n';}if($('ocrPreview')&&generation===ocrGeneration)$('ocrPreview').innerHTML=`<img class="image-preview" alt="${L('本地输入预览','Local input preview')}" src="${canvases[0].toDataURL('image/png')}">`;}if(generation!==ocrGeneration)return;state.text=text;if($('measurementText'))$('measurementText').value=text;state.parsed=parseMeasurements(text);if($('parsedFields'))$('parsedFields').innerHTML=parsedFields();if($('ocrStatus'))$('ocrStatus').textContent=L('完成；逐字段复核后应用','Complete; review before applying');}catch(error){if(generation===ocrGeneration)toast(L('识别失败：','Extraction failed: ')+error.message);}finally{state.importBusy=false;}}
function evidence(){const cv=model.research_validation,t=model.temporal_test,i=study.inference;$('content').innerHTML=`<div class="metric-strip">${metric(L('内部 CV R²','Internal CV R²'),n(cv.r2,3),'',L('患者分组重复嵌套验证','Repeated nested patient-grouped validation'),true)}${metric(L('内部 CV MAE','Internal CV MAE'),n(cv.mae,1),'μm',`95% CI ${n(cv.mae_ci95[0],1)}–${n(cv.mae_ci95[1],1)}`)}${metric(L('时间测试 MAE','Temporal-test MAE'),n(t.mae,1),'μm',`95% CI ${n(t.mae_ci95[0],1)}–${n(t.mae_ci95[1],1)}`)}${metric(L('目标 PI 80%：时间覆盖','Nominal PI 80%: temporal coverage'),pct(t.coverage80),'',L('实际覆盖不足，默认改用 95%','Undercoverage; 95% is the default'))}</div><div class="grid-2">${panel(L('校准：第一轮折外分箱均值','Calibration: first-repeat outer-CV bins'),calibrationChart()+`<p class="dense-note">${L('仅显示 n≥5 的预测分箱均值，未公开逐眼点。点大小表示分箱眼数。','Only prediction-bin means with n≥5 are shown. Individual points are not published; circle size reflects bin count.')}</p>`)}${panel(L('证据边界','Evidence boundaries'),`<div class="evidence-status">${[[L('患者分组与折内调参','Patient grouping and inner tuning'),L('已执行','Executed'),'teal'],[L('2025 年时间测试','2025 temporal test'),L('29 眼 / 15 人','29 eyes / 15 patients'),''],[L('独立中心外部验证','Independent-centre external validation'),L('尚无','Absent'),'amber'],[L('事件概率独立校准','Independent event-probability calibration'),L('尚无','Absent'),'amber'],[L('伦理、作者、机构元数据','Ethics, authors and institution'),L('待研究方确认','Author confirmation needed'),'amber']].map(([a,b,c])=>`<div><span>${a}</span><span class="tag ${c}">${b}</span></div>`).join('')}</div><div class="space-top">${note(L('同中心时间测试不等于多中心外部验证。早期模型的柱镜口径有歧义，本次观察到的完整病例四变量结果不能与旧 397 眼结果直接互换。','A same-centre temporal test is not multicentre external validation. Historical cylinder coding is ambiguous; complete-case four-variable results cannot substitute for the legacy 397-eye result.'))}</div>`)}</div><div class="space-top">${panel(L('11 个候选模型 · 同一开发队列','11 candidate models · same development cohort'),`<div class="table-scroll"><table><thead><tr><th>${L('模型','Model')}</th><th>MAE (μm)</th><th>95% CI</th><th>RMSE</th><th>R²</th><th>±200 μm</th></tr></thead><tbody>${Object.entries(study.models).sort((a,b)=>a[1].mae-b[1].mae).map(([key,r])=>`<tr class="${key===study.selection.browser_default?'selected':''}"><td>${modelLabel(key)} ${key===study.selection.browser_default?'<span class="tag teal">'+L('默认','Default')+'</span>':''}</td><td>${n(r.mae,1)}</td><td>${n(r.mae_ci95[0],1)}–${n(r.mae_ci95[1],1)}</td><td>${n(r.rmse,1)}</td><td>${n(r.r2,3)}</td><td>${pct(r.within200)}</td></tr>`).join('')}</tbody></table></div><p class="dense-note space-top">${L('MAE 等指标是三次重复验证的损失平均值，不是先平均三次预测后再评分。CI 对固定折外预测进行患者聚类重抽样，没有包含完整模型选择过程的变异。','Metrics average losses across three repetitions, not averaged predictions. CIs resample patients conditional on fixed OOF predictions, not the entire selection process.')}</p>`)}<div class="grid-2 space-top">${panel(L('可复算的解剖发现','Recomputed anatomical findings'),`<div class="insight-list"><div class="insight"><span class="insight-dot"></span><div><b>STS-V − STS-H = ${n(i.sulcus_anisotropy.difference,2)} mm</b><p>95% CI ${n(i.sulcus_anisotropy.ci95[0],2)}–${n(i.sulcus_anisotropy.ci95[1],2)} · n=${i.sulcus_anisotropy.n}</p></div></div><div class="insight"><span class="insight-dot"></span><div><b>${L('STS 代理 KS：轴向匹配降低 MAE','STS-proxy KS: axis matching reduces MAE')} ${n(i.KS_axis_improvement.mae_reduction,1)} μm</b><p>95% CI ${n(i.KS_axis_improvement.ci95[0],1)}–${n(i.KS_axis_improvement.ci95[1],1)} · ${L('同批 394 眼；未测 ATA，属于改写公式','Same 394 eyes; ATA unmeasured, modified formula')}</p></div></div></div>`)}${panel(L('交互结果应降级为探索性','Interaction findings remain exploratory'),`<p class="section-note">${L('在不把柱镜缺失填 0 的完整观测病例中，早期“尺寸×方位”交互的患者聚类区间跨 0，p=0.146；1 个月 p=0.057。不能继续把旧稿的显著结果当作稳健复现。','With observed cylinder only, the early size×orientation interaction patient-cluster CI crosses zero (p=0.146); one-month p=0.057. The legacy significant claim is not a robust replication.')}</p>${note(L('真正有支撑的是沟径各向异性、轴匹配的误差改善，以及患者分组的可复现验证。','Supported findings are sulcus anisotropy, axis-matched error reduction and reproducible patient-grouped validation.'))}`)}</div><div class="space-top">${panel(L('复现与下载','Reproducibility & downloads'),`<div class="download-list"><a class="download-row" href="research/results.json" download><span>${L('完整汇总结果','Full aggregate results')}</span><small>JSON ↓</small></a><a class="download-row" href="research/model-comparison.csv" download><span>${L('模型比较表','Model comparison')}</span><small>CSV ↓</small></a><a class="download-row" href="assets/model.json" download><span>${L('冻结的模型系数','Frozen model coefficients')}</span><small>JSON ↓</small></a><a class="download-row" href="docs/analysis-protocol.md"><span>${L('拟合前分析计划','Pre-fit analysis protocol')}</span><small>MD ↗</small></a></div>`)}</div>`;}
function poster(){ $('content').innerHTML=`<div class="grid-wide">${panel(L('壁报草稿 · A0 竖版','Poster draft · A0 portrait'),`<a href="poster/ICL_A0_draft.pdf"><img class="poster-preview" src="poster/ICL_A0_preview.png" alt="${L('患者分组ICL拱高预测壁报草稿','Draft poster on patient-grouped ICL vault research')}"></a><div class="import-actions"><a class="button blue" href="poster/ICL_A0_draft.pdf" download>PDF ↓</a><a class="button" href="poster/poster.html">${L('可编辑网页壁报','Editable web poster')} ↗</a><a class="button" href="docs/poster-plan.md">${L('投稿与选题计划','Submission and study plan')} ↗</a></div>`,`<span class="tag amber">${L('待作者与伦理确认','Author / ethics pending')}</span>`)}<div class="stack">${panel(L('这个项目适不适合？','Is this project a good fit?'),`<div class="insight-list"><div class="insight"><span class="insight-dot"></span><div><b>${L('综合眼科 / 屈光手术场次：有条件适合','General ophthalmology / refractive track: conditionally suitable')}</b><p>${L('ESCRS 2025 PO1048 是 ICL 长期拱高预测壁报；ASCRS 2025 收录 OCT 深度学习拱高预测壁报。','ESCRS 2025 PO1048 is an ICL longitudinal-vault poster; ASCRS 2025 lists an OCT deep-learning vault poster.')}</p></div></div><div class="insight"><span class="insight-dot" style="background:var(--amber)"></span><div><b>${L('纯低视力康复场次：当前匹配较弱','Dedicated low-vision rehabilitation: weaker fit')}</b><p>${L('拱高是解剖终点。本研究没有证明视功能康复疗效，不宜用“康复获益”包装。','Vault is an anatomical endpoint. This study does not establish functional rehabilitation benefit.')}</p></div></div></div>`)}${panel(L('建议保留项目，重构研究主线','Retain the project; sharpen the research question'),note(L('主壁报突出“患者分组验证 + 轴向匹配 + 时间迁移边界”。后续优先考虑“1 个月实测值对 6 个月拱高的增量预测”，并补充真实视觉功能终点。','The main poster emphasizes patient grouping, axis matching and temporal-transfer limits. Prioritize the incremental value of observed month-one vault for six-month outcomes and add genuine functional outcomes.')))}${panel(L('投稿前必须补齐','Before submission'),`<div class="event-list"><div><small>MEETING</small><b>${L('会议全名、截止日期、尺寸与摘要规格','Meeting name, deadline, size and abstract rules')}</b><p>${L('未查到可核实的目标场次壁报通知；目前为通用 A0 草稿。','No verified call for this exact target meeting was found; this is a generic A0 draft.')}</p></div><div><small>AUTHORSHIP</small><b>${L('作者、单位、贡献与伦理文件','Authors, affiliations, contributions and ethics')}</b><p>${L('由研究方填写真实信息，草稿未代填审批号。','The study team must supply actual metadata; no approval number is invented.')}</p></div></div>`)}</div></div><div class="space-top">${panel(L('研究报告与本次会话','Study report & session summary'),`<div class="import-actions"><a class="button" href="docs/research-report.md">${L('研究成果总结','Research results report')} ↗</a><button class="button" data-action="report">${L('生成当前研究小结','Generate session summary')}</button><button class="button" data-action="selfcheck">${L('运行数值自检','Run numerical checks')}</button></div><div id="selfcheckResults"></div>`)}</div>`;}

function reportHTML(){return `<h1 class="report-title">EVO ICL · ${L('研究情景小结','Research scenario summary')}</h1><p class="print-muted">${model.id} · ${L('分析版本','Analysis version')} 2026-10-13 · ${new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'})}</p><p>${L('本小结描述本次会话的模型实验；不是病历、手术建议或经临床验证的患者报告。','This summary describes a model experiment in this session. It is not a medical record, surgical recommendation or clinically validated patient report.')}</p>${['OD','OS'].filter(e=>e==='OD'||state.bilateral).map(eye=>{const p=prediction(eye);if(!p.valid)return `<h2>${eye}</h2><p>${L('输入无效','Invalid inputs')}: ${esc(p.errors.join(', '))}</p>`;return `<section class="print-break"><h2>${eye} · ${n(p.y)} μm</h2><p>${state.level}% PI: ${n(p.band[0])}–${n(p.band[1])} μm · ${L('残差模型估计概率','Residual-model probability estimates')}: &lt;250 ${pct(p.probabilities.low)} / 250–750 ${pct(p.probabilities.middle)} / &gt;750 ${pct(p.probabilities.high)}</p><table><tbody>${['acd','lt','stsh','stsv','size','toric','angle'].map(k=>`<tr><td>${name(k)}</td><td>${n(p.resolved[k],k==='angle'||k==='toric'?0:2)}</td></tr>`).join('')}</tbody></table>${p.fallback||p.tails.length?`<p>${L('探索性回退或队列边缘参数，当前区间未单独校准。','Exploratory fallback or cohort-tail inputs; intervals are not separately calibrated for these conditions.')}</p>`:''}</section>`;}).join('')}<h2>${L('验证证据','Validation evidence')}</h2><p>${L('开发集患者分组验证','Development patient-grouped CV')}: MAE ${n(model.research_validation.mae,1)} μm / R² ${n(model.research_validation.r2,3)}; ${L('2025 时间测试','2025 temporal test')}: MAE ${n(model.temporal_test.mae,1)} μm, n=29 ${L('眼 / 15 人','eyes / 15 patients')}.</p><p>${L('80% 标称区间时间覆盖 65.5%；95% 区间时间覆盖 96.6%。概率未独立校准，无独立中心外部验证。','Nominal 80% temporal coverage 65.5%; 95% temporal coverage 96.6%. Probabilities are not independently calibrated; there is no independent-centre external validation.')}</p><p class="print-muted">${L('研究用途。由临床研究团队核查数据、作者和伦理信息；不用于医疗决策。','Research use. The study team must verify data, authorship and ethics; not for clinical decisions.')} https://calculator.evo-icl.cn</p>`;}
function modal(title,body){$('modalTitle').textContent=title;$('modalBody').innerHTML=body;$('modal').showModal();}
function showReport(){modal(L('研究情景小结','Research scenario summary'),reportHTML()+`<div class="import-actions"><button class="button blue" id="printButton">${L('打印 / 保存 PDF','Print / save PDF')}</button><button class="button" id="downloadReport">HTML ↓</button></div>`);$('printButton').onclick=()=>{$('printReport').innerHTML=reportHTML();window.print();};$('downloadReport').onclick=()=>download('ICL-research-summary.html','<!doctype html><meta charset="utf-8"><style>body{font:14px/1.8 sans-serif;max-width:800px;margin:40px auto;padding:20px}table{width:100%;border-collapse:collapse}td{border-bottom:1px solid #ddd;padding:6px}</style>'+reportHTML(),'text/html');}
function modelCard(){modal(L('模型说明 · v3.0','Model card · v3.0'),`<span class="tag teal">${L('冻结于 2022–2024 开发集','Frozen on 2022–2024 development data')}</span><dl class="model-definition"><dt>${L('主要终点','Endpoint')}</dt><dd>${L('术后 1 个月拱高，μm','One-month postoperative vault, μm')}</dd><dt>${L('开发队列','Development')}</dt><dd>341 ${L('眼 / 173 名患者','eyes / 173 patients')}</dd><dt>${L('时间测试','Temporal test')}</dt><dd>29 ${L('眼 / 15 名患者','eyes / 15 patients')} · 2025</dd><dt>${L('模型','Model')}</dt><dd>Ridge · α=10 · 6 ${L('变量','features')}</dd><dt>${L('输入来源','Inputs')}</dt><dd>Pentacam ACD · UBM STS-H/V · Jingxin900 LT · ICL / Toric / θ</dd></dl><div class="formula">${equation()}</div><ul><li>${L('80% 区间在时间测试中覆盖不足；默认展示 95%。','80% intervals undercovered in temporal testing; 95% is the default.')}</li><li>${L('三类概率依赖开发集折外残差，未独立校准。','Three-range probabilities depend on development OOF residuals and are not independently calibrated.')}</li><li>${L('改变尺寸/方位的情景属于统计关联，未建立因果效果。','Size/orientation scenarios describe associations; causal effects are unestablished.')}</li><li>${L('CLR/STSL 未测，无多中心外部验证，无视觉康复获益证据。','CLR/STSL unmeasured; no multicentre external validation or evidence of functional rehabilitation benefit.')}</li></ul>`+note(L('研究演示，不用于临床决策。','Research demonstrator, not for clinical decisions.')));}
function download(filename,content,type='application/json'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function sessionData(){return {schema:'vault-lab-3',model:model.id,eyes:state.eyes,follow:state.follow,pinned:state.pinned,bilateral:state.bilateral,target:state.target,level:state.level};}
function cleanEye(candidate){
 if(!candidate||typeof candidate!=='object')throw new Error('Eye measurements are required');
 const clean={};
 for(const key of ['acd','lt','stsh','stsv','wtw','size','toric','angle'])clean[key]=M.finite(candidate[key])?Number(candidate[key]):'';
 clean.source=candidate.source==='wtw'?'wtw':'measured';
 if(!M.predict(clean,model).valid)throw new Error('Invalid measurement values');
 return clean;
}
function importSession(value){
 if(!value||value.schema!=='vault-lab-3'||!value.eyes)throw new Error('Unsupported session schema');
 const eyes={OD:cleanEye(value.eyes.OD),OS:cleanEye(value.eyes.OS)},pinned=[];
 for(const item of (Array.isArray(value.pinned)?value.pinned:[]).slice(0,10)){
  try{
   const eyeData=cleanEye(item.eyeData),level=item.level===80?80:95,result=M.predict(eyeData,model,{level});
   pinned.push({eye:item.eye==='OS'?'OS':'OD',eyeData,y:result.y,band:result.band,level});
  }catch{/* Invalid scenarios are omitted rather than trusting saved output values. */}
 }
 state.eyes=eyes;state.pinned=pinned;state.bilateral=value.bilateral!==false;state.eye=state.bilateral?state.eye:'OD';state.level=value.level===80?80:95;
 if(Array.isArray(value.target)&&value.target.length===2&&value.target.every(v=>M.finite(v)&&v>=0&&v<=1500)&&Number(value.target[0])!==Number(value.target[1]))state.target=value.target.map(Number).sort((a,b)=>a-b);
 state.follow={OD:{},OS:{}};
 for(const eye of ['OD','OS'])for(const key of ['early','month1','month3','month6']){const v=value.follow?.[eye]?.[key];if(M.finite(v)&&v>=0&&v<=1500)state.follow[eye][key]=Number(v);}
}
function selfchecks(){const e=initialEye(),p=M.predict(e,model),tests=[['horizontal STS',Math.abs(M.effectiveSTS(11.8,12.2,0)-11.8)<1e-10],['vertical STS',Math.abs(M.effectiveSTS(11.8,12.2,90)-12.2)<1e-10],['probability sum',Math.abs(p.probabilities.low+p.probabilities.middle+p.probabilities.high-1)<1e-10],['PI order',p.band[0]<p.y&&p.y<p.band[1]],['empty input rejected',!M.predict({...e,acd:''},model).valid],['unit error rejected',!M.predict({...e,acd:3200},model).valid],['target inversion',Math.abs(M.probabilities(p.y,model.residual_histogram,600,400).target-M.probabilities(p.y,model.residual_histogram,400,600).target)<1e-12],['CSV quotes',M.parseCSV('acd,note\n3.2,"a,b"')[0].acd==='3.2']];return tests;}
function setPage(page){if(!pages.some(p=>p[0]===page))page='overview';state.page=page;render();$('workspace').focus({preventScroll:true});}
function render(){const meta=pages.find(p=>p[0]===state.page);document.documentElement.lang=state.lang==='zh'?'zh-CN':'en';$('navigation').innerHTML=pages.map(p=>`<a href="#${p[0]}" class="${state.page===p[0]?'active':''}" ${state.page===p[0]?'aria-current="page"':''}><span class="nav-glyph" aria-hidden="true">${p[1]}</span>${L(p[2],p[3])}</a>`).join('');$('breadcrumbPage').textContent=L(meta[2],meta[3]);$('pageEyebrow').textContent=meta[4];$('pageTitle').textContent=L(meta[5],meta[6]);$('pageDescription').textContent=L(meta[7],meta[8]);$('languageToggle').textContent=state.lang==='zh'?'English':'中文';$('railLabel').textContent=L('研究工作站','RESEARCH WORKSPACE');$('breadcrumbRoot').textContent=L('眼科研究','Ophthalmic research');$('localLabel').textContent=L('本地计算','Local computation');$('modelCardButton').textContent=L('模型说明','Model card');$('exportButton').textContent=L('导出研究小结','Research summary');$('railStudyNote').innerHTML=L('患者分组验证<br>2022–2024 开发 · 2025 时间测试','Patient-grouped validation<br>2022–2024 development · 2025 test');$('footerUse').textContent=L('研究演示 · 未经独立外部验证 · 不用于临床决策','Research demonstration · no external validation · not for clinical decisions');$('footerEvidence').textContent=L('方法与证据 ↗','Methods & evidence ↗');({overview,experiment,scenarios,followup,import:importPage,evidence,poster}[state.page])();}
document.addEventListener('click',event=>{const button=event.target.closest('button,a');if(!button)return;if(button.dataset.go){location.hash=button.dataset.go;return;}if(button.dataset.eye){state.eye=button.dataset.eye;render();return;}if(button.dataset.source){state.eyes[state.eye].source=button.dataset.source;experiment();return;}if(button.dataset.size){state.eyes[state.eye].size=Number(button.dataset.size);experiment();return;}if(button.dataset.scenario){const [size,angle]=button.dataset.scenario.split(',').map(Number);Object.assign(state.eyes[state.eye],{size,angle});location.hash='experiment';if(state.page==='experiment')render();return;}if(button.dataset.unpin!==undefined){state.pinned.splice(Number(button.dataset.unpin),1);render();return;}if(button.dataset.apply){const eye=button.dataset.apply,merged={...state.eyes[eye],...state.parsed};const check=M.predict(merged,model);if(!check.valid){toast(L('字段范围未通过：','Fields failed validation: ')+check.errors.map(name).join('/'));return;}state.eyes[eye]=merged;state.eye=eye;state.bilateral=eye==='OS'?true:state.bilateral;location.hash='experiment';return;}const action=button.dataset.action;if(!action)return;switch(action){case 'reset-eye':state.eyes[state.eye]=initialEye(state.eye==='OS'?{angle:90}:{});render();break;case 'pin':{const p=prediction(state.eye);if(!p.valid)return;if(state.pinned.length>=10){toast(L('最多暂存 10 个情景','Maximum 10 pinned scenarios'));return;}state.pinned.push({eye:state.eye,eyeData:{...state.eyes[state.eye]},y:p.y,band:p.band,level:p.level});toast(L('已暂存研究情景','Research scenario pinned'));break;}case 'report':showReport();break;case 'target-reset':state.target=[250,750];scenarios();break;case 'sample-text':state.text=sampleText;state.parsed=parseMeasurements(sampleText);importPage();break;case 'parse':state.text=$('measurementText').value;if(state.text.length>200000){toast(L('文本过长','Text too long'));return;}state.parsed=parseMeasurements(state.text);$('parsedFields').innerHTML=parsedFields();break;case 'sample-csv':state.batch=sampleCSV;importPage();break;case 'batch-run':batchRun();break;case 'batch-export':if(!state.batchOutput.length){toast(L('先运行批量','Run the batch first'));return;}download('vault-batch.csv','row,estimate_um,pi_low_um,pi_high_um,status\n'+state.batchOutput.map(r=>[r.row,r.p.valid?n(r.p.y,2):'',r.p.valid?n(r.p.band[0],2):'',r.p.valid?n(r.p.band[1],2):'',r.p.valid?'valid':'invalid'].join(',')).join('\n'),'text/csv');break;case 'export-json':download('vault-research-session.json',JSON.stringify(sessionData(),null,2));break;case 'clear-import':state.text='';state.parsed={};ocrGeneration++;importPage();break;case 'wipe':state.text='';state.batch='';state.parsed={};state.batchOutput=[];state.follow={OD:{},OS:{}};state.pinned=[];state.eyes={OD:initialEye(),OS:initialEye({angle:90})};ocrGeneration++;if(ocrWorker){ocrWorker.terminate();ocrWorker=null;}render();toast(L('已清空会话','Session cleared'));break;case 'share':modal(L('分享合成研究参数','Share synthetic research parameters'),`<p>${L('链接会包含双眼测量参数。请确认它们是合成数据且适合公开分享。','The link contains bilateral measurement inputs. Confirm that these are synthetic and suitable for public sharing.')}</p><label class="section-note"><input type="checkbox" id="shareConsent"> ${L('我确认只分享合成演示参数','I confirm these are synthetic demonstration inputs')}</label><div class="import-actions"><button class="button blue" id="createShare" disabled>${L('生成链接','Generate link')}</button></div><div id="shareResult"></div>`);$('shareConsent').onchange=()=>{$('createShare').disabled=!$('shareConsent').checked;};$('createShare').onclick=()=>{const payload={schema:'vault-lab-3',eyes:state.eyes,bilateral:state.bilateral,level:state.level,target:state.target};const json=JSON.stringify(payload),code=btoa(unescape(encodeURIComponent(json))),url=location.origin+location.pathname+'#share='+encodeURIComponent(code);$('shareResult').innerHTML=`<textarea readonly aria-label="Share link">${esc(url)}</textarea>`;};break;case 'selfcheck':const checks=selfchecks();$('selfcheckResults').innerHTML=`<div class="check-results">${checks.map(([title,pass])=>`${pass?'PASS':'FAIL'} · ${title}`).join('<br>')}</div>`;break;}});
document.addEventListener('input',event=>{const input=event.target;if(input.dataset.field){state.eyes[state.eye][input.dataset.field]=input.value;const other=$(input.id.startsWith('num-')?'range-'+input.dataset.field:'num-'+input.dataset.field);if(other)other.value=input.value;refreshExperiment();}if(input.dataset.observed){state.follow[state.eye][input.dataset.observed]=input.value;if($('followupResult'))$('followupResult').innerHTML=followupResult();}if(input.dataset.parsed)state.parsed[input.dataset.parsed]=M.finite(input.value)?Number(input.value):'';if(input.id==='measurementText')state.text=input.value;if(input.id==='batchText')state.batch=input.value;});
document.addEventListener('change',async event=>{const input=event.target;if(input.id==='toric'){state.eyes[state.eye].toric=Number(input.value);refreshExperiment();}if(input.id==='bilateral'){state.bilateral=input.checked;if(!state.bilateral)state.eye='OD';render();}if(input.id==='level'){state.level=Number(input.value);render();}if(input.id==='targetLow'||input.id==='targetHigh'){const low=Number($('targetLow').value),high=Number($('targetHigh').value);if(!M.finite($('targetLow').value)||!M.finite($('targetHigh').value)||low===high||low<0||high<0||low>1500||high>1500){toast(L('目标区需为两个不同的 0–1500 μm 数值','Target bounds must be different values within 0–1500 μm'));$('targetLow').value=state.target[0];$('targetHigh').value=state.target[1];return;}const next=[Math.min(low,high),Math.max(low,high)];if(next.every((v,i)=>v===state.target[i]))return;state.target=next;$('targetLow').value=state.target[0];$('targetHigh').value=state.target[1];$('scenarioRows').innerHTML=scenarioRows();$('heatmap').innerHTML=heatmap();}if(input.id==='ocrFile'&&input.files[0])loadOCR(input.files[0]);if(input.id==='csvFile'&&input.files[0]){if(input.files[0].size>2e6){toast(L('文件超过 2 MB','File exceeds 2 MB'));return;}state.batch=await input.files[0].text();$('batchText').value=state.batch;}if(input.id==='jsonFile'&&input.files[0]){try{if(input.files[0].size>1e6)throw new Error('File exceeds 1 MB');importSession(JSON.parse(await input.files[0].text()));render();toast(L('会话已导入','Session imported'));}catch(error){toast(L('导入失败：','Import failed: ')+error.message);}}});
$('languageToggle').onclick=()=>{state.lang=state.lang==='zh'?'en':'zh';render();};$('modelCardButton').onclick=modelCard;$('exportButton').onclick=showReport;$('modalClose').onclick=()=>$('modal').close();$('modal').addEventListener('click',event=>{if(event.target===$('modal')){const rect=$('modal').getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)$('modal').close();}});$('menuToggle').onclick=()=>{const rail=document.querySelector('.rail');rail.classList.toggle('open');$('menuToggle').setAttribute('aria-expanded',String(rail.classList.contains('open')));};
window.addEventListener('hashchange',()=>{document.querySelector('.rail').classList.remove('open');$('menuToggle').setAttribute('aria-expanded','false');setPage(location.hash.slice(1));});
if(location.hash.startsWith('#share=')){try{const code=decodeURIComponent(location.hash.slice(7));if(code.length>10000)throw new Error('Share payload too long');importSession(JSON.parse(decodeURIComponent(escape(atob(code)))));history.replaceState(null,'',location.pathname+'#experiment');state.page='experiment';}catch(error){history.replaceState(null,'',location.pathname+'#overview');toast(L('分享参数无效','Invalid shared parameters'));}}else state.page=pages.some(p=>p[0]===location.hash.slice(1))?location.hash.slice(1):'overview';
window.VaultApp={getState:()=>JSON.parse(JSON.stringify(state)),selfchecks,importSession,parseMeasurements,prediction,render,reportHTML};
render();
